  if (lastAcceleration) {
    var delta = Math.abs(current.x - lastAcceleration.x) + Math.abs(current.y - lastAcceleration.y) + Math.abs(current.z - lastAcceleration.z)
    var now = Date.now()
    if (delta > 5 && now - lastWakeAt > 3000) {
      lastWakeAt = now
      raiseWakeCallback()
    }
  }

  lastAcceleration = current
}

